changeSet.sql:
-- The legacy cart merchant_domain was also used as the outbound routing trust anchor. -- Preserve that authority before replacing presentation identity with the verified storefront. UPDATE cart SET routing_domain = merchant_domain WHERE merchant_domain IS NOT NULL;
WITH integration_authority AS ( SELECT integration.id, integration.provider, nullif(lower(btrim(integration.verified_domain)), '') AS verified_domain, lower(split_part( split_part(substring(integration.endpoint FROM 9), '/', 1), ':', 1 )) AS endpoint_host FROM merchant_integration integration WHERE integration.endpoint ~* '^https://[a-z0-9][a-z0-9.-]*($|:[0-9]{1,5}$|/[^[:space:]]*$|:[0-9]{1,5}/[^[:space:]]*$)' AND integration.endpoint !~ '@' ) UPDATE cart SET routing_domain = CASE WHEN authority.verified_domain IS NOT NULL AND ( authority.endpoint_host = authority.verified_domain OR authority.endpoint_host LIKE '%.' || authority.verified_domain ) THEN authority.verified_domain ELSE authority.endpoint_host END FROM integration_authority authority WHERE cart.merchant_integration_id = authority.id AND cart.provider = authority.provider;
WITH verified_shopify_storefront AS ( SELECT identity.normalized_value AS shop_identity, merchant.domain AS merchant_domain FROM merchant_identity identity JOIN merchant ON merchant.id = identity.merchant_id WHERE identity.namespace = 'SHOPIFY_SHOP' AND identity.role = 'PROVIDER_ID' ) UPDATE cart SET merchant_domain = storefront.merchant_domain FROM verified_shopify_storefront storefront WHERE cart.provider = 'SHOPIFY' AND cart.merchant_integration_id IS NULL AND cart.merchant_id IS NULL AND lower(btrim(cart.external_merchant_id)) = storefront.shop_identity;
-- A technical Shopify source host is not a safe presentation fallback. Old carts without -- a verified storefront claim remain executable through routing_domain but display no domain. UPDATE cart SET merchant_domain = NULL WHERE provider = 'SHOPIFY' AND merchant_integration_id IS NULL AND merchant_id IS NULL AND NOT EXISTS ( SELECT 1 FROM merchant_identity identity WHERE identity.namespace = 'SHOPIFY_SHOP' AND identity.role = 'PROVIDER_ID' AND identity.normalized_value = lower(btrim(cart.external_merchant_id)) );

-- Checkout attribution gives us both authorities without trusting the legacy inventory field. UPDATE user_inventory_items inventory SET external_merchant_domain = cart.routing_domain, merchant_origin = cart.merchant_domain FROM cart WHERE inventory.source_checkout_attempt_id = cart.checkout_attempt_id AND cart.checkout_attempt_id IS NOT NULL;
UPDATE user_inventory_items inventory SET merchant_origin = merchant.domain FROM merchant_integration integration JOIN merchant ON merchant.id = integration.merchant_id WHERE inventory.merchant_origin IS NULL AND inventory.merchant_integration_id = integration.id;
WITH verified_shopify_storefront AS ( SELECT identity.normalized_value AS shop_identity, merchant.domain AS merchant_origin FROM merchant_identity identity JOIN merchant ON merchant.id = identity.merchant_id WHERE identity.namespace = 'SHOPIFY_SHOP' AND identity.role = 'PROVIDER_ID' ) UPDATE user_inventory_items inventory SET merchant_origin = storefront.merchant_origin FROM verified_shopify_storefront storefront WHERE inventory.merchant_origin IS NULL AND inventory.provider = 'SHOPIFY' AND lower(btrim(inventory.external_merchant_id)) = storefront.shop_identity;
-- A legacy domain becomes presentation data only when it matches a verified storefront claim. WITH verified_domain AS ( SELECT identity.normalized_value AS domain, merchant.domain AS merchant_origin FROM merchant_identity identity JOIN merchant ON merchant.id = identity.merchant_id WHERE identity.namespace = 'DOMAIN' AND identity.role = 'STOREFRONT_DOMAIN' ) UPDATE user_inventory_items inventory SET merchant_origin = verified.merchant_origin FROM verified_domain verified WHERE inventory.merchant_origin IS NULL AND lower(btrim(inventory.external_merchant_domain)) = verified.domain;
